::view-transition-group(root) {
    animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}

::view-transition-new(root) {
    mask: var(--inhaus-polygon-gradient) top left / 0 no-repeat;
    mask-origin: top left;
    animation: inhaus-theme-scale 1.5s both;
}

::view-transition-old(root) {
    animation: none;
    z-index: -1;
}

@keyframes inhaus-theme-scale {
    to { mask-size: 200vmax; }
}

@media (prefers-reduced-motion: reduce) {
    ::view-transition-group(root),
    ::view-transition-new(root),
    .inhaus-theme-wipe {
        animation-duration: 1ms !important;
    }
}

/* Typography Overrides */
h1, h2, h3, .sipy-word {
    font-family: 'Sora', sans-serif !important;
    font-weight: 800 !important;
}

/* Custom Topbar Header styling */
.custom-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 0px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    margin-bottom: 30px;
    position: relative;
}
.custom-header-right {
    display: flex;
    align-items: center;
    gap: 16px;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
    min-width: fit-content !important;
}
.agency {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-left: 44px;
}
.agency img {
height: 26px;
width: auto;
}
.agency .div-bar {
    width: 1px;
    height: 22px;
    background: rgba(255,255,255,0.14);
}
.agency .who {
    font-size: 12px;
    color: #8A97A8;
    font-weight: 600;
    letter-spacing: .02em;
}
.stamp {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    color: #8A97A8;
    font-weight: 600;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
    min-width: fit-content !important;
}
.stamp .live {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #02569e;
    box-shadow: 0 0 0 0 rgba(2,86,158,0.6);
    animation: pulse 2s infinite;
}
@keyframes pulse {
0% { box-shadow: 0 0 0 0 rgba(2,86,158,0.5); }
70% { box-shadow: 0 0 0 8px rgba(2,86,158,0); }
100% { box-shadow: 0 0 0 0 rgba(2,86,158,0); }
}

.loading-overlay {
position: fixed;
top: 0;
left: 0;
width: 100vw;
height: 100vh;
background-color: rgba(10, 13, 19, 0.95);
z-index: 999999;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
}
.loading-text {
font-family: 'Sora', sans-serif;
color: #02569e;
font-size: 24px;
margin-top: 20px;
font-weight: 800;
}
.spinner {
border: 6px solid rgba(255, 255, 255, 0.1);
width: 70px;
height: 70px;
border-radius: 50%;
border-left-color: #02569e;
animation: spin 1s linear infinite;
}
@keyframes spin {
0% { transform: rotate(0deg); }
100% { transform: rotate(360deg); }
}

/* Brand styling */
.eyebrow {
    font-size: 11px;
    font-weight: 800;
    letter-spacing: .2em;
    text-transform: uppercase;
    color: #02569e;
}
.lede {
    color: #8A97A8;
    font-size: 15px;
